import java.util.Scanner;

abstract class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    abstract void speak();
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：喵～");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：汪！");
    }
}

class Fish extends Animal {
    Fish(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：咕噜咕噜");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rounds = sc.nextInt();
        Animal[] pets = { new Cat("{cat}"), new Dog("{dog}"), new Fish("{fishName}") };
        for (int r = 0; r < rounds; r++) {
            for (Animal pet : pets) {
                pet.speak();
            }
        }
    }
}
